    /// An enum modeling the different authentication modes
    #[repr(u8)]
    pub enum AuthMode {

        /// PASE authentication
        Pase = AccessControlEntryAuthModeEnum::PASE as _,

        /// CASE authentication
        Case = AccessControlEntryAuthModeEnum::CASE as _,

        /// Group authentication
        Group = AccessControlEntryAuthModeEnum::Group as _,
    }
    #[allow(non_upper_case_globals, unused_qualifications)]
    const _: () =
        {
            #[allow(clippy :: useless_attribute)]
            #[allow(rust_2018_idioms)]
            extern crate num_traits as _num_traits;
            impl _num_traits::FromPrimitive for AuthMode {
                #[allow(trivial_numeric_casts)]
                #[inline]
                fn from_i64(n: i64) -> ::core::option::Option<Self> {
                    if n == AuthMode::Pase as i64 {
                        ::core::option::Option::Some(AuthMode::Pase)
                    } else if n == AuthMode::Case as i64 {
                        ::core::option::Option::Some(AuthMode::Case)
                    } else if n == AuthMode::Group as i64 {
                        ::core::option::Option::Some(AuthMode::Group)
                    } else { ::core::option::Option::None }
                }
                #[inline]
                fn from_u64(n: u64) -> ::core::option::Option<Self> {
                    Self::from_i64(n as i64)
                }
            }
        };
    #[automatically_derived]
