                [0x43, 0x6f, 0x6d, 0x70, 0x72, 0x65, 0x73, 0x73, 0x65, 0x64,
                        0x46, 0x61, 0x62, 0x72, 0x69, 0x63];
            let mut compressed_fabric_id = [0; COMPRESSED_FABRIC_ID_LEN];
            match crate::fmt::Try::into_result(hkdf_sha256(&fabric_id.to_be_bytes(),
                        root_pubkey, &COMPRESSED_FABRIC_ID_INFO,
                        &mut compressed_fabric_id)) {
                ::core::result::Result::Ok(t) => t,
                ::core::result::Result::Err(e) => {
                    {
                        ::core::panicking::panic_fmt(format_args!("unwrap of `{0}` failed: {1:?}",
                                "hkdf_sha256(&fabric_id.to_be_bytes(), root_pubkey, &COMPRESSED_FABRIC_ID_INFO,\n&mut compressed_fabric_id,)",
                                e));
                    };
                }
            };
            u64::from_be_bytes(compressed_fabric_id)
