                                        ::log::__private_api::log({
                                                ::log::__private_api::GlobalLogger
                                            },
                                            format_args!("\n>>RCV {0}\n      => No space for a new encrypted session, dropping",
                                                packet), lvl,
                                            &("rs_matter::transport", "rs_matter::transport",
                                                    ::log::__private_api::loc()), ());
