        fn handle_dropped_exchange<const N :
            usize>(&self, packet: &mut Packet<N>) -> Result<bool, Error> {
            let mut session_mgr = self.session_mgr.borrow_mut();
            let exch =
                session_mgr.get_exch(|_, exch|
                                exch.role.is_dropped_state() &&
                                    exch.mrp.is_retrans_pending()).map(|(sess, exch_index)|
                            (sess.id, exch_index,
                                true)).or_else(||
                        {
                            session_mgr.get_exch(|_, exch|
                                        {
                                            exch.role.is_dropped_state() &&
                                                !exch.mrp.is_retrans_pending()
                                        }).map(|(sess, exch_index)| (sess.id, exch_index, false))
                        });
            let Some((session_id, exch_index, close_session)) =
                exch else { return Ok(exch.is_none()); };
            let exchange_id = ExchangeId::new(session_id, exch_index);
            if close_session {
                {
                    {
                        {
                            let lvl = ::log::Level::Error;
                            if lvl <= ::log::STATIC_MAX_LEVEL &&
                                    lvl <= ::log::max_level() {
                                ::log::__private_api::log({
                                        ::log::__private_api::GlobalLogger
                                    },
                                    format_args!("Dropped exchange {0}: Closing session because the exchange cannot be closed cleanly",
                                        exchange_id.display(match crate::fmt::Try::into_result(session_mgr.get(session_id))
                                                {
                                                ::core::result::Result::Ok(t) => t,
                                                ::core::result::Result::Err(e) => {
                                                    {
                                                        ::core::panicking::panic_fmt(format_args!("unwrap of `{0}` failed: {1:?}",
                                                                "session_mgr.get(session_id)", e));
                                                    };
                                                }
                                            })), lvl,
                                    &("rs_matter::transport", "rs_matter::transport",
                                            ::log::__private_api::loc()), ());
                            }
                        }
                    };
                };
                self.encode_evict_session(packet, &mut session_mgr,
                        session_id)?;
            } else {
                let session =
                    match crate::fmt::Try::into_result(session_mgr.get(session_id))
                        {
                        ::core::result::Result::Ok(t) => t,
                        ::core::result::Result::Err(e) => {
                            {
                                ::core::panicking::panic_fmt(format_args!("unwrap of `{0}` failed: {1:?}",
                                        "session_mgr.get(session_id)", e));
                            };
                        }
                    };
                let exchange =
                    match crate::fmt::Try::into_result(session.exchanges[exch_index].as_mut())
                        {
                        ::core::result::Result::Ok(t) => t,
                        ::core::result::Result::Err(e) => {
                            {
                                ::core::panicking::panic_fmt(format_args!("unwrap of `{0}` failed: {1:?}",
                                        "session.exchanges[exch_index].as_mut()", e));
                            };
                        }
                    };
                if exchange.mrp.is_ack_pending() {
                    self.encode_packet(packet, Some(session), Some(exch_index),
                            |_| { Ok(Some(OpCode::MRPStandAloneAck.into())) })?;
                }
                {
                    {
                        {
                            let lvl = ::log::Level::Warn;
                            if lvl <= ::log::STATIC_MAX_LEVEL &&
                                    lvl <= ::log::max_level() {
                                ::log::__private_api::log({
                                        ::log::__private_api::GlobalLogger
                                    },
                                    format_args!("Dropped exchange {0}: Closed",
                                        exchange_id.display(session)), lvl,
                                    &("rs_matter::transport", "rs_matter::transport",
                                            ::log::__private_api::loc()), ());
                            }
                        }
                    };
                };
                session.exchanges[exch_index] = None;
            }
            Ok(exch.is_none())
        }
        pub(crate) async fn evict_some_session(&self) -> Result<(), Error> {
            let mut tx =
                self.get_if(&self.tx, |packet| packet.buf.is_empty()).await;
            tx.clear_on_drop(true);
            let evicted = self.encode_evict_some_session(&mut tx)?;
            if evicted {
                tx.clear_on_drop(false);
                Ok(())
            } else { Err(ErrorCode::NoSpaceSessions.into()) }
        }
        fn decode_packet<const N : usize>(&self, packet: &mut Packet<N>)
            -> Result<bool, Error> {
            packet.header.reset();
            let mut pb =
                ParseBuf::new(&mut packet.buf[packet.payload_start..]);
            packet.header.plain.decode(&mut pb)?;
            let mut session_mgr = self.session_mgr.borrow_mut();
            let epoch = session_mgr.epoch;
            let set_payload =
                |packet: &mut Packet<N>, (start, end)|
                    { packet.payload_start = start; packet.buf.truncate(end); };
            if let Some(session) =
                    session_mgr.get_for_rx(&packet.peer, &packet.header.plain) {
                let payload_range =
                    session.decode_remaining(&mut packet.header, pb)?;
                set_payload(packet, payload_range);
                return session.post_recv(&packet.header, epoch);
            }
            if !packet.header.plain.is_encrypted() {
                packet.header.decode_remaining(&mut pb, 0, None)?;
                packet.header.proto.adjust_reliability(true, &packet.peer);
                let payload_range = pb.slice_range();
                set_payload(packet, payload_range);
                if MessageMeta::from(&packet.header.proto).is_new_session() {
                    let session =
                        session_mgr.add(false, packet.peer,
                                packet.header.plain.get_src_nodeid())?;
                    return session.post_recv(&packet.header, epoch);
                }
            } else { set_payload(packet, (0, 0)); }
            Err(ErrorCode::NoSession.into())
        }
        fn encode_packet<const N : usize,
            F>(&self, packet: &mut Packet<N>,
            mut session: Option<&mut Session>, exchange_index: Option<usize>,
            payload_writer: F) -> Result<(), Error> where
            F: FnOnce(&mut WriteBuf) -> Result<Option<MessageMeta>, Error> {
            match crate::fmt::Try::into_result(packet.buf.resize_default(N)) {
                ::core::result::Result::Ok(t) => t,
                ::core::result::Result::Err(e) => {
                    {
                        ::core::panicking::panic_fmt(format_args!("unwrap of `{0}` failed: {1:?}",
                                "packet.buf.resize_default(N)", e));
                    };
                }
            };
            let mut wb = WriteBuf::new(&mut packet.buf);
            wb.reserve(PacketHdr::HDR_RESERVE)?;
            let Some(meta) =
                payload_writer(&mut wb)? else {
                    packet.buf.clear();
                    return Ok(());
                };
            meta.set_into(&mut packet.header.proto);
            let retransmission =
                if let Some(session) = &mut session {
                    packet.header.plain = Default::default();
                    let (peer, retransmission) =
                        session.pre_send(exchange_index, &mut packet.header,
                                self.device_sai, self.device_sii)?;
                    packet.peer = peer;
                    retransmission
                } else {
                    if packet.header.plain.is_encrypted() ||
                                packet.header.plain.get_src_nodeid().is_none() ||
                            packet.header.proto.is_reliable() {
                        Err(ErrorCode::NoSession)?;
                    }
                    let src_nodeid = packet.header.plain.get_src_nodeid();
                    packet.header.plain = Default::default();
                    packet.header.plain.sess_id = 0;
                    packet.header.plain.ctr = 1;
                    packet.header.plain.set_src_nodeid(None);
                    packet.header.plain.set_dst_unicast_nodeid(src_nodeid);
                    packet.header.proto.unset_initiator();
                    packet.header.proto.adjust_reliability(false, &packet.peer);
                    false
                };
            {
                {
                    {
                        let lvl = ::log::Level::Debug;
                        if lvl <= ::log::STATIC_MAX_LEVEL &&
                                lvl <= ::log::max_level() {
                            ::log::__private_api::log({
                                    ::log::__private_api::GlobalLogger
                                },
                                format_args!("\n<<SND {0}\n      => {1} (system)",
                                    Packet::<0>::display(&packet.peer, &packet.header),
                                    if retransmission { "Re-sending" } else { "Sending" }), lvl,
                                &("rs_matter::transport", "rs_matter::transport",
                                        ::log::__private_api::loc()), ());
                        }
                    }
                };
            };
            {
                {
                    {
                        let lvl = ::log::Level::Trace;
                        if lvl <= ::log::STATIC_MAX_LEVEL &&
                                lvl <= ::log::max_level() {
                            ::log::__private_api::log({
                                    ::log::__private_api::GlobalLogger
                                },
                                format_args!("{0}",
                                    Packet::<0>::display_payload(&packet.header.proto,
                                        wb.as_slice())), lvl,
                                &("rs_matter::transport", "rs_matter::transport",
                                        ::log::__private_api::loc()), ());
                        }
                    }
                };
            };
            if let Some(session) = session {
                session.encode(&packet.header, &mut wb)?;
            } else { packet.header.encode(&mut wb, 0, None)?; }
            let range = (wb.get_start(), wb.get_tail());
            packet.payload_start = range.0;
            packet.buf.truncate(range.1);
            Ok(())
        }
        fn encode_evict_some_session<const N :
            usize>(&self, packet: &mut Packet<N>) -> Result<bool, Error> {
            let mut session_mgr = self.session_mgr.borrow_mut();
            let id =
                session_mgr.get_session_for_eviction().map(|sess| sess.id);
            if let Some(id) = id {
                self.encode_evict_session(packet, &mut session_mgr, id)?;
                Ok(true)
            } else {
                {
                    {
                        {
                            let lvl = ::log::Level::Error;
                            if lvl <= ::log::STATIC_MAX_LEVEL &&
                                    lvl <= ::log::max_level() {
                                ::log::__private_api::log({
                                        ::log::__private_api::GlobalLogger
                                    },
                                    format_args!("All sessions have active exchanges, cannot evict any session"),
                                    lvl,
                                    &("rs_matter::transport", "rs_matter::transport",
                                            ::log::__private_api::loc()), ());
                            }
                        }
                    };
                };
                Ok(false)
            }
        }
        fn encode_evict_session<const N :
            usize>(&self, packet: &mut Packet<N>,
            session_mgr: &mut SessionMgr, id: u32) -> Result<(), Error> {
            packet.header.proto.exch_id = session_mgr.get_next_exch_id();
            packet.header.proto.set_initiator();
            let mut session =
                match crate::fmt::Try::into_result(session_mgr.remove(id)) {
                    ::core::result::Result::Ok(t) => t,
                    ::core::result::Result::Err(e) => {
                        {
                            ::core::panicking::panic_fmt(format_args!("unwrap of `{0}` failed: {1:?}",
                                    "session_mgr.remove(id)", e));
                        };
                    }
                };
            self.session_removed.notify();
            {
                {
                    {
                        let lvl = ::log::Level::Debug;
                        if lvl <= ::log::STATIC_MAX_LEVEL &&
                                lvl <= ::log::max_level() {
                            ::log::__private_api::log({
                                    ::log::__private_api::GlobalLogger
                                },
                                format_args!("Evicting session {0} [SID:{1:x},RSID:{2:x}]",
                                    session.id, session.get_local_sess_id(),
                                    session.get_peer_sess_id()), lvl,
                                &("rs_matter::transport", "rs_matter::transport",
                                        ::log::__private_api::loc()), ());
                        }
                    }
                };
            };
            self.encode_packet(packet, Some(&mut session), None,
                    |wb| { sc_write(wb, SCStatusCodes::CloseSession, &[]) })?;
            Ok(())
        }
        fn is_close_session(payload: &mut [u8]) -> Result<bool, Error> {
            let mut pb = ParseBuf::new(payload);
            let report = StatusReport::read(&mut pb)?;
            let close_session =
                report.proto_id == PROTO_ID_SECURE_CHANNEL as u32 &&
                    report.proto_code == SCStatusCodes::CloseSession as u16;
            Ok(close_session)
        }
