    pub mod ipv6 {
        use core::net::Ipv6Addr;
        /// Create a link-local IPv6 address from a MAC address.
        ///
        /// Note that this function does not perform any SLAAC-related operations
        /// like checking whether the generated address is already in use.
        pub fn create_link_local_ipv6(mac: &[u8; 6]) -> Ipv6Addr {
            Ipv6Addr::new(0xfe80, 0, 0, 0,
                u16::from_be_bytes([mac[0] ^ 0x02, mac[1]]),
                u16::from_be_bytes([mac[2], 0xff]),
                u16::from_be_bytes([0xfe, mac[3]]),
                u16::from_be_bytes([mac[4], mac[5]]))
        }
    }
    pub mod iter {
        /// An extension trait for `Iterator` implementing several utility methods.
        pub trait TryFindIterator<T, E>: Iterator<Item = Result<T, E>> +
            Sized {
            /// Find the first element that satisfies the supplied `predicate`.
            ///
            /// Method name is `do_try_find` to avoid collissions with `Iterator::try_find`
            /// once it gets stabilized.
            fn do_try_find<P>(self, mut predicate: P) -> Result<Option<T>, E>
                where P: FnMut(&T) -> Result<bool, E> {
                for val in self {
                    let val = val?;
                    let result = predicate(&val);
                    match result {
                        Ok(matches) => { if matches { return Ok(Some(val)); } }
                        Err(err) => { return Err(err); }
                    }
                }
                Ok(None)
            }
        }
        impl<T, I, E> TryFindIterator<T, E> for I where
            I: Iterator<Item = Result<T, E>> {}
    }
